# The main binary itself may have enough in the dynsym. Let's get ALL exported function symbols with sizes 
# and see if any match our addresses directly (offset 0 or small offset)
python3 << 'EOF'
import subprocess

# Get all dynamic symbols with sizes using readelf-like output
result = subprocess.run(['llvm-readelf', '--dyn-syms', 'libmonosgen-2.0.so'], 
                      capture_output=True, text=True)

# Parse the output
symbols = []
for line in result.stdout.strip().split('\n'):
    parts = line.split()
    if len(parts) >= 8 and parts[3] == 'FUNC':
        try:
            addr = int(parts[1], 16)
            size = int(parts[2])
            name = parts[7].split('@')[0]  # strip version info
            if addr > 0 and size > 0:
                symbols.append((addr, size, name))
        except (ValueError, IndexError):
            continue

symbols.sort(key=lambda x: x[0])
print(f"Total function symbols with size: {len(symbols)}")

def lookup(pc):
    for addr, size, name in symbols:
        if addr <= pc < addr + size:
            return f"{name}+0x{pc - addr:x}"
    # Fallback: nearest below
    best = None
    for addr, size, name in symbols:
        if addr <= pc:
            best = (addr, size, name)
        else:
            break
    if best:
        return f"{best[2]}+0x{pc - best[0]:x} (nearest, size=0x{best[1]:x})"
    return "??"

addrs = [
    ('Thread 7020 (main) #01', 0x222098),
    ('Thread 7020 (main) #02', 0x2241ac),
    ('Thread 7020 (main) #03', 0x1abc80),
    ('Thread 7020 (main) #04', 0x16de04),
    ('Thread 7046 (SGen worker) #02', 0x2f4b20),
    ('Thread 7046 (SGen worker) #03', 0x2f4c84),
    ('Thread 7048 (Finalizer) #02', 0x2c1a40),
]

for label, pc in addrs:
    print(f"  {label}: pc 0x{pc:08x} -> {lookup(pc)}")
EOF", "description": "Lookup with sized function symbols"}

